export const getComponentNameFromRef = (ref, section) => {
    if (!ref.startsWith('#'))
        return undefined;
    let pointer;
    try {
        pointer = decodeURIComponent(ref.slice(1));
    }
    catch (_a) {
        return undefined;
    }
    const prefix = `/components/${section}/`;
    if (!pointer.startsWith(prefix))
        return undefined;
    const token = pointer.slice(prefix.length);
    if (token.length === 0 || token.includes('/'))
        return undefined;
    return token.replace(/~1/g, '/').replace(/~0/g, '~');
};
export const getSecuritySchemeNameFromFragment = (key) => getComponentNameFromRef(key, 'securitySchemes');
